effect.shader:
float gmHash(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);}
void main(){
vec2 size=max(inputImg.size,vec2(1.0)); float frame=floor(acTime*24.0+evolution*17.0); vec2 uv=acScreenNorm;
uv+=(vec2(gmHash(vec2(frame,1.0)),gmHash(vec2(frame,2.0)))-0.5)*gateWeave/size;
vec4 src=texture2DCv(inputImg.texture,clamp(uv,0.0,1.0)); float n=gmHash(floor(acScreenNorm*size)+frame)-0.5;
float col=floor(acScreenNorm.x*220.0); float scratchSeed=gmHash(vec2(col,floor(frame*0.12))); float sx=abs(fract(acScreenNorm.x*220.0+scratchSeed)-0.5);
float scratch=step(1.0-scratches*0.08,scratchSeed)*(1.0-smoothstep(0.015,0.06,sx));
vec2 dustCell=floor(acScreenNorm*vec2(90.0,55.0)); float dr=gmHash(dustCell+frame*0.37); vec2 dl=fract(acScreenNorm*vec2(90.0,55.0))-0.5;
float dustMask=step(1.0-dust*0.08,dr)*(1.0-smoothstep(0.08,0.45,length(dl)));
float pulse=1.0+(gmHash(vec2(frame,9.0))-0.5)*flicker; vec3 aged=mix(src.rgb,src.rgb*stainColor.rgb,age*0.38)*pulse;
aged+=n*grain; aged=mix(aged,vec3(0.96),scratch*0.75); aged=mix(aged,vec3(0.03),dustMask*0.65);
gl_FragColor=vec4(mix(src.rgb,aged,mixAmount),src.a);
}
